// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address caller, uint256 amount, address target) public {
        vm.assume(amount <= type(uint256).max / 2);
        vm.assume(target != address(c));
        vm.assume(caller != address(0));

        vm.deal(caller, amount);

        uint256 initialContractBalance = address(c).balance;
        uint256 initialRecordedBalance = c.getBalance(target);

        vm.prank(caller);
        c.addToBalance{value: amount}();

        uint256 recordedBalanceIncrease = c.getBalance(caller) - (caller == target ? initialRecordedBalance : c.getBalance(target));
        uint256 actualContractBalanceIncrease = address(c).balance - initialContractBalance;

        assertTrue(actualContractBalanceIncrease == recordedBalanceIncrease);
    }
}
